CASES=[
('ספקטור נ׳ צרפתי (ע״א 838/75)','מוכר מגרש לא גילה לקבלן שמתוכננת הפקעה חלקית שמאפשרת לבנות רק 12 דירות ולא 16. הקבלן לא שאל.','מקרה קשה של אי-גילוי. אשר: לפי ערכי החברה חובה לגלות, והיכולת של הצד השני לבדוק בעצמו אינה משחררת. לנדוי: אין חובה, יש גבול לדאגה כלפי אנשי עסקים. עם השנים המגמה המרחיבה ניצחה. המבחן לתום לב אובייקטיבי.'),
('פנידר נ׳ קסטרו (ד״נ 7/81)','מנהל חברת נדל״ן מכר דירה בפרויקט על מגרש שלא היה בבעלות החברה; החברה נקלעה לפירוק והקונה תבע אישית את המנהל.','חובת תום הלב במשא ומתן היא אישית וחלה על כל מי שמשתתף בפועל, גם אם אינו צד פורמלי לחוזה (מנהל, עורך דין, נציג מכירות). גם דוגמה "פשוטה" לאי-גילוי.'),
('קוט נ׳ ארגון הדיירים (ע״א 800/75)','ארגון דיירים ניהל משא ומתן למכירת חנות בעוד שהחנות כבר נמכרה לאחר, לטענתו בטעות.','תום לב אינו דורש כוונת זדון; המבחן אובייקטיבי. משא ומתן "סרק" גם מרשלנות הוא חוסר תום לב. המושג המשפטי כולל רשלנות.'),
('שיכון עובדים נ׳ זפניק (ע״א 829/80)','זוג שנמנע מלהירשם למבצע בשל עומס וחוסר ארגון של החברה; התגלגל לפשרה והם תבעו את ההפרש.','אמרת אגב של השופטת בן-פורת: "אשם בהתקשרות" – חסימה אקטיבית של הצד השני ואחר כך טענה "לא נכרת חוזה" – חוסר תום לב. ובמקרים חריגים התרופה יכולה להיות אכיפה, ולא רק פיצויים (סעיף 12(א) כעקרון-על).'),
('מזר נ׳ גאון','"הצעת רכישה" לדירה מקבלן; הקבלן הציב אולטימטום וסעיף הוצאות חדש כשהמחירים עלו.','אין חוזה (פרטים מהותיים חסרים; הקפדה גם בגלל פערי כוח צרכן-קבלן), אך כל השופטים: פרישה בשלב מתקדם משיקולי כדאיות בלבד, ברגע האחרון, באולטימטום – חוסר תום לב. ניתן לתבוע פיצויים בשל כך.'),
('בית יולס נ׳ רביב (ד״נ 22/82)','מכרז פרטי לבניית בית אבות בתנאי סף של ערבות בנקאית; המזמין בחר בהצעה שלא כללה ערבות.','בדעת רוב נקבע באותה תקופה שאין חובת שוויון במכרז פרטי (חופש החוזים). המכרז הוא "תחרות ממוסדת" והפנייה היא הזמנה להציע הצעות.'),
]
QS=[
Q('מה היה השינוי התפיסתי שהכניס חוק החוזים (1973) בעניין המשא ומתן?','מעבר מתפיסת המשא ומתן כתחרות בין יריבים לתפיסת הצדדים כשותפים החייבים בתום לב',['מעבר ממשא ומתן בעל פה למשא ומתן בכתב','איסור מוחלט על ניהול משא ומתן מקביל','חובה לחתום על חוזה בתום המשא ומתן'],'לפני 1973 המשא ומתן נתפס כתחרות (על כל צד לבדוק ולשאול). סעיף 12 החדיר נורמות של הגינות וצדק וראה בצדדים שותפים.'),
Q('מהו המבחן לתום לב במשא ומתן בפסיקה הישראלית?','אובייקטיבי: התאמת ההתנהגות לערכי החברה, בלי קשר להשקפת עולמו האישית של הפועל',['סובייקטיבי: האם הפועל שלם עם לבו','כוונת זדון של הפועל','מבחן מעורב שבו הכוונה הפנימית מכריעה'],'תום לב אובייקטיבי: מה החברה מצפה מאדם סביר. אין משמעות לכך שהאדם משוכנע שהוא "צדיק".'),
Q('מה נכון לגבי הביטוי "בדרך מקובלת ובתום לב" בסעיף 12?','בפסיקה "דרך מקובלת" נבלעה תחת "תום לב" האובייקטיבי ואין לה משמעות נפרדת',['"דרך מקובלת" היא המבחן האובייקטיבי ו"תום לב" הסובייקטיבי','"דרך מקובלת" מחייבת שימוש בנוהג המסחרי בלבד','"תום לב" מתייחס רק לשלב ביצוע החוזה'],'גישה שהפרידה בין שני המונחים לא התקבלה. תום הלב הוא המבחן האובייקטיבי הכולל.'),
Q('בפרשת ספקטור נ׳ צרפתי, מדוע לפי המבחן הסובייקטיבי ספקטור היה נוהג בתום לב?','כי לדעתו לא נשאל, והקבלן מקצועי שיכול היה לבדוק מידע פומבי, ולכן הוא משוכנע שנהג כשורה',['כי הוא גילה את המידע בכתב','כי המתווך גילה את המידע לקבלן','כי חוק החוזים אינו מחייב גילוי מידע'],'במבחן סובייקטיבי נבחנת האמונה הפנימית. ספקטור האמין שהוא נוהג כשורה. אבל המבחן אובייקטיבי: מה החברה מצפה ממוכר.'),
Q('מה עמד במחלוקת בין השופט אשר לשופט לנדוי בפרשת ספקטור נ׳ צרפתי?','האם ערכי החברה מחייבים גילוי מידע גם כשהצד השני מקצועי ויכול לבדוק בעצמו',['האם החוזה נכרת בכתב','האם סעיף 12 חל על מכרזים','האם המתווך אחראי לנזק'],'אשר: חובה לגלות, היכולת לבדוק אינה משחררת. לנדוי: אין חובה, יש גבול לדאגה הנדרשת מאנשי עסקים. המגמה המרחיבה ניצחה.'),
Q('מדוע פסק הדין פנידר נ׳ קסטרו נחשב דוגמה "פשוטה" לאי-גילוי?','כי ברור לכל שהסתרת העובדה שהמגרש אינו בבעלות החברה מנוגדת לערכי היסוד של החברה',['כי הצדדים היו חברי ילדות','כי נכרת חוזה בכתב','כי החברה נכנסה לפירוק'],'בפנידר ברור שאי-גילוי כזה סותר ערכי חברה בסיסיים. בספקטור, לעומת זאת, קשה להכריע ולכן הוא "מקרה קשה".'),
Q('מהו החידוש העיקרי של פנידר נ׳ קסטרו?','החובה לנהוג בתום לב במשא ומתן היא אישית, וחלה על כל המשתתף בפועל גם אם אינו צד לחוזה',['חובת תום הלב חלה רק על חברות','חובת תום הלב חלה רק על מי שחתם על החוזה','אין אחריות אישית בסעיף 12'],'הנתבע טען שאינו "צד". נקבע שהחובה אישית: מנהל, עורך דין או נציג מכירות שנהגו שלא בתום לב חשופים לתביעה אישית.'),
Q('בפרשת קוט נ׳ ארגון הדיירים הארגון טען שמכר את החנות לאחר "בטעות". מה קבע בית המשפט?','תום לב אינו מחייב כוונת זדון; משא ומתן סרק, אפילו מרשלנות, הוא חוסר תום לב',['טעות אינה חוסר תום לב לעולם','חוסר תום לב מחייב כוונה לפגוע','הארגון נהג כשורה כי הוא לא ידע על המכירה'],'המבחן אובייקטיבי. מי שמנהל משא ומתן צפוי לוודא שהוא מסוגל לקיים את החוזה. רשלנות מספיקה.'),
Q('מהו היחס בין רשלנות לחוסר תום לב?','חפיפה משמעותית אך לא זהות מוחלטת; לא כל רשלנות היא אוטומטית חוסר תום לב',['הם זהים לחלוטין','אין ביניהם קשר','חוסר תום לב הוא רק כוונת זדון'],'המובן המשפטי של תום לב רחב ויכול לכלול רשלנות; אך לא כל חוסר תשומת לב הוא חוסר תום לב.'),
Q('מהו "אשם בהתקשרות"?','מצב שבו צד אחד חוסם באופן אקטיבי את הצד השני מלכרות את החוזה, ולאחר מכן טוען "לא נכרת חוזה"',['כל פרישה ממשא ומתן','אי-גילוי של מידע מהותי','תביעה בשל הפרת חוזה'],'זפניק: החברה גרמה בבלגן שלה לכך שהזוג לא יכול היה להירשם, ואחר כך טענה שלא נכרת חוזה. אדם אינו יכול להיות האשם במניעה והנהנה ממנה.'),
Q('מה אמרה השופטת בן-פורת בזפניק בעניין התרופות?','שבמקרים חריגים של "אשם בהתקשרות" אפשר לפסוק אכיפה ולא רק פיצויים, מכוח סעיף 12(א) כעקרון-על',['שאין לפסוק תרופה בגין חוסר תום לב במשא ומתן','שהתרופה היחידה היא ביטול החוזה','שהפיצויים אינם אפשריים בסעיף 12'],'אמרת אגב: רשימת התרופות אינה סגורה. סעיף 12(א) הוא חובה כללית ("עקרון-על"), וסעיף 12(ב) קובע רק כללים לפיצויים אם נבחר בהם.'),
Q('מהו הכלל לגבי פרישה ממשא ומתן בשלב מתקדם?','נדרשת הצדקה עניינית וטובה; כדאיות כלכלית פתאומית אינה מספיקה',['הפרישה מותרת תמיד כל עוד לא נחתם חוזה','הפרישה אסורה לחלוטין','הפרישה מותרת רק בהסכמת הצד השני'],'בשלב מתקדם נוצרת ציפייה לגיטימית. הצדקות: שינוי קיצוני בנסיבות, תרמית וכד׳. לא די בכך שהעסקה פחות משתלמת.'),
Q('איזו מהבאות היא הצדקה עניינית לפרישה בשלב מתקדם?','פריצת מלחמה או אסון טבע שמשנים קיצונית את הנסיבות',['העסקה נראית פתאום פחות משתלמת','הופיע קונה חדש שמציע יותר','נמאס לצד אחד לנהל משא ומתן'],'הצדקות: שינוי קיצוני בנסיבות, תרמית של הצד השני וכו׳. כדאיות כלכלית פתאומית או הצעה טובה יותר אינן הצדקה.'),
Q('בפרשת מזר נ׳ גאון, למה לא ניתן צו מניעה זמני?','כי הסיכוי להוכיח שנכרת חוזה היה קלוש: חסרים פרטים מהותיים',['כי הקבלן לא פעל בחוסר תום לב','כי הקונים לא שילמו דמי רצינות','כי הבקשה הוגשה באיחור'],'צו מניעה זמני מחייב סיכויי תביעה טובים (כריתת חוזה). חסרו שטח הדירה, המפרט הטכני, ומועד תשלום לא קוים. אך הקבלן נהג בחוסר תום לב ולכן הוצע מסלול תביעת פיצויים.'),
Q('מדוע בית המשפט הקפיד בדרישות גמירת הדעת והמסוימות בעסקה בין קבלן לצרכן במזר נ׳ גאון?','כדי למנוע מקבלנים "לכלוא" צרכנים בעסקאות על בסיס מסמך ראשוני, שכן בדרך כלל הצרכן הוא המתחרט',['כי הקבלן חזק יותר ולכן מרוויח','כי חוק המכר דורש חוזה בכתב','כי הצרכן אינו כשיר משפטית'],'שיקול חברתי של הגנת צרכן ופערי כוח: אם מסמך ראשוני ייחשב בקלות חוזה, קבלנים עלולים לנצל זאת.'),
Q('מה ההגדרה של "מכרז" בפסיקה?','תחרות ממוסדת, שבה הפנייה של המזמין היא הזמנה להציע הצעות',['כל פנייה לקבלת הצעות','משא ומתן חופשי בין שני צדדים','חוזה שנחתם בנוכחות עורך דין'],'הגדרה פסיקתית: תחרות ממוסדת – יש כללים מסודרים (מועד סופי, תנאי סף, קריטריונים). הפנייה של המזמין אינה הצעה.'),
Q('מי מציע ומי ניצע במכרז?','המשתתף מציע (מגיש הצעה), והמזמין ניצע שמקבל ההצעה הזוכה בקיבול',['המזמין מציע והמשתתף ניצע','שניהם מציעים','אין הצעה וקיבול במכרז'],'המזמין אינו רוצה להיות המציע; הפנייה שלו היא "הזמנה להציע הצעות". החוזה משתכלל כשהוא מבצע קיבול כלפי ההצעה הזוכה.'),
Q('איזה דין חל על מכרז פרטי?','חוק החוזים בלבד, וכללי ההתנהגות נגזרים מחובת תום הלב (סעיף 12)',['חוק חובת המכרזים','אין שום דין','חוק עשיית עושר ולא במשפט'],'חוק חובת המכרזים חל על מכרזים ציבוריים. במכרז פרטי חל חוק החוזים, ותום הלב הוא המסגרת.'),
Q('מה נקבע בבית יולס נ׳ רביב לגבי מכרז פרטי?','בדעת רוב נקבע באותה תקופה שאין חובת שוויון במכרז פרטי, בהסתמך על חופש החוזים',['חובה לנהוג בשוויון מוחלט במכרז פרטי','המזמין חייב לבחור את ההצעה הזולה ביותר','מכרז פרטי בטל אם אין ערבות'],'בית המשפט הדגיש חופש חוזים וכי במכרז פרטי המשתתפים אינם מצפים לשוויון מוחלט.'),
Q('בפרשת קל בניין, מדוע לא נכרת חוזה?','כי הוסכם שהקיבול יתקיים רק לאחר החלטה רשמית של מועצת המנהלים, והיא טרם התקבלה',['כי המחיר לא סוכם','כי לא נחתם זיכרון דברים','כי קל בניין חזרה בה'],'נקבע שהפרוטוקול של מועצת המנהלים היה תנאי הכרחי לכריתה. המיעוט סבר שבישיבה עם כוסיות ייתכן שכבר נכרת חוזה.'),
Q('חברה ניהלה משא ומתן מתקדם והגיעה להסכמות, ואז פרשה כי קיבלה הצעה גבוהה יותר. איזו טענה תתאים לצד הנפגע?','חוסר תום לב במשא ומתן (סעיף 12): פרישה בשלב מתקדם בלי הצדקה עניינית',['הפרת חוזה, כי נכרת חוזה בכל מקרה','ביטול החוזה לפי פרק ב׳','חוסר שפיטות'],'אם לא נכרת חוזה – הפרישה בלי הצדקה היא חוסר תום לב לפי סעיף 12. אין "הפרת חוזה" כשלא נכרת חוזה, ופרק ב׳ חל רק אם נכרת חוזה.'),
Q('מה נכון לגבי הקשר בין כריתת חוזה לתום לב?','הן שתי שאלות נפרדות; ייתכן חוזה בין רמאים וייתכן שלא נכרת חוזה בין אנשים הגונים',['תום לב הוא תנאי לכריתת חוזה','חוסר תום לב מבטל כל חוזה','תום לב נבחן רק אם נכרת חוזה'],'כריתה ותום לב הן קומות שונות בקומה הראשונה. ניתן לתבוע על חוסר תום לב גם בלי חוזה.'),
]
